modify_existing.before:
it('[AC-B1-01zzo#10] couli.yaml 其余规则不变：分组、顺序、alert 名、表达式、for 与标签与 B1-01zzh 一致，只有拒绝写入一条的窗口变成 [10m]，couli-sync 组另加 CouliPddServiceFeeMissing 一条', () => {
  const all = rules();
  const lastSync = EXPECTED.findIndex((rule) => rule.alert === 'CouliSyncWatermarkLag');
  expect([...new Set(all.map((rule) => rule.group))]).toEqual([
    'couli-queue',
    'couli-sync',
    'couli-redis',
    'couli-union',
    // B3-08za（D10-1060 / D10-1087）：Agent trace 缺失告警自成一组，追加在最后。
    'couli-agent',
  ]);
  // B1-04zy adds the Taobao search fallback alert in a group of its own, after the others. Its
  // window, threshold and hold are not this file's: [AC-B1-04zy#58] pins the expression's shape.
  const fallbackAlert = {
    group: 'couli-union',
    alert: 'CouliTaobaoSearchFallbackHigh',
    expr: expect.stringContaining('couli_taobao_search_total'),
    for: expect.stringMatching(/^[1-9][0-9]*[smh]$/),
    labels: { severity: 'warning' },
  };
  expect(
    all.map(({ group, alert, expr, for: holdFor, labels }) => ({
      group,
      alert,
      expr,
      for: holdFor,
      labels,
    })),
  ).toEqual([
    ...EXPECTED.slice(0, lastSync + 1),
    {
      group: 'couli-sync',
      alert: 'CouliPddServiceFeeMissing',
      expr: 'increase(couli_pdd_service_fee_missing_total[1h]) > 0',
      for: '5m',
      labels: { severity: 'warning' },
    },
    // B1-08zy（D10-1003）：couli-sync 组在 CouliPddServiceFeeMissing 之后追加按 platform 分组的新告警。
    {
      group: 'couli-sync',
      alert: 'CouliServiceFeeMissing',
      expr: 'sum by (platform) (increase(couli_service_fee_missing_total[1h])) > 0',
      for: '5m',
      labels: { severity: 'warning' },
    },
    ...EXPECTED.slice(lastSync + 1),
    fallbackAlert,
    // B3-08za（D10-1060 / D10-1087）：couli-agent 组的 Agent trace 缺失告警（运维类，夜间静默）。
    {
      group: 'couli-agent',
      alert: 'CouliAgentTraceMissing',
      expr: 'couli_agent_trace_missing_runs > 0',
      for: '5m',
      labels: { severity: 'warning' },
    },
  ]);
  for (const rule of all) {
    const summary = rule.annotations['summary'];
    expect(summary, `${rule.alert}.annotations.summary`).toEqual(expect.any(String));
    expect((summary as string).trim().length, `${rule.alert} summary`).toBeGreaterThan(0);
  }
});

